const CombatMoveInfo *ArenaPlatinum_GetMoveInfo(uint16_t move)
{
    if (move == 0 || move >= ARENA_PLATINUM_MOVE_COUNT) return 0;
    return &sMoveInfo[move];
}

uint8_t ArenaPlatinum_GetStatusEffect(uint16_t move)
{
    if (move == 0 || move >= ARENA_PLATINUM_MOVE_COUNT) return ARENA_STATUS_NONE;
    return sStatusEffects[move];
}

const struct ArenaMoveProfile *ArenaPlatinum_GetFallbackProfile(uint16_t move)
{
    if (move == 0 || move >= ARENA_PLATINUM_MOVE_COUNT) return 0;
    return &sFallbackProfiles[move];
}
